/* =========================================================
   ✈ AIRLINE BOOKING FORM
   VISUAL ONLY — DO NOT CHANGE FUNCTIONALITY
   ========================================================= */

/* ---------- PAGE BACKGROUND ---------- */
body {
    background:
        linear-gradient(135deg, #eef6ff 0%, #f8fbff 45%, #eef4ff 100%) !important;
    min-height: 100vh !important;
}


/* ---------- MAIN WEB FORM CONTAINER ---------- */
.web-form-container {
    max-width: 900px !important;
    margin: 45px auto !important;
    padding: 0 20px !important;
}


/* ---------- MAIN CARD ---------- */
.web-form-container .form-page {
    background: #ffffff !important;
    border-radius: 24px !important;
    padding: 42px 48px !important;

    border: 1px solid #dbeafe !important;

    box-shadow:
        0 20px 50px rgba(30, 64, 175, 0.12),
        0 4px 12px rgba(15, 23, 42, 0.06) !important;

    position: relative !important;
    overflow: hidden !important;
}


/* ---------- BLUE TOP AIRLINE STRIPE ---------- */
.web-form-container .form-page::before {
    content: "" !important;
    position: absolute !important;
    top: 0 !important;
    left: 0 !important;
    right: 0 !important;
    height: 6px !important;

    background: linear-gradient(
        90deg,
        #1d4ed8,
        #2563eb,
        #38bdf8
    ) !important;
}


/* ---------- TITLE ---------- */
.web-form-container h1 {
    font-size: 32px !important;
    font-weight: 800 !important;
    color: #0f172a !important;

    text-align: center !important;

    margin-top: 5px !important;
    margin-bottom: 10px !important;

    letter-spacing: -0.5px !important;
}


/* ---------- TITLE DECORATION ---------- */
.web-form-container h1::before {
    content: "✈  " !important;
    color: #2563eb !important;
}


/* ---------- INTRODUCTION ---------- */
.web-form-container .introduction {
    text-align: center !important;

    color: #64748b !important;
    font-size: 15px !important;

    margin-bottom: 32px !important;
}


/* ---------- HORIZONTAL LINE ---------- */
.web-form-container hr {
    border: 0 !important;
    border-top: 1px solid #e2e8f0 !important;
    margin: 20px 0 30px !important;
}


/* ---------- SECTION HEADINGS ---------- */
.web-form-container .section-head {
    font-size: 18px !important;
    font-weight: 700 !important;

    color: #1e3a8a !important;

    border-left: 4px solid #2563eb !important;

    padding-left: 12px !important;

    margin-top: 28px !important;
    margin-bottom: 20px !important;
}


/* ---------- FIELD LABELS ---------- */
.web-form-container .control-label {
    font-size: 13px !important;
    font-weight: 700 !important;

    color: #334155 !important;

    margin-bottom: 7px !important;
}


/* ---------- REQUIRED STAR ---------- */
.web-form-container .control-label .reqd {
    color: #ef4444 !important;
}


/* ---------- FIELD SPACING ---------- */
.web-form-container .form-group {
    margin-bottom: 20px !important;
}


/* ---------- ALL INPUTS ---------- */
.web-form-container .form-control {
    min-height: 45px !important;

    border-radius: 11px !important;

    border: 1px solid #d7e0ea !important;

    background: #ffffff !important;

    color: #0f172a !important;

    padding: 10px 14px !important;

    font-size: 14px !important;

    transition:
        border-color 0.2s ease,
        box-shadow 0.2s ease,
        transform 0.2s ease !important;
}


/* ---------- INPUT HOVER ---------- */
.web-form-container .form-control:hover {
    border-color: #93c5fd !important;
}


/* ---------- INPUT FOCUS ---------- */
.web-form-container .form-control:focus {
    border-color: #2563eb !important;

    box-shadow:
        0 0 0 3px rgba(37, 99, 235, 0.12) !important;

    outline: none !important;
}


/* ---------- FETCHED / READONLY FIELDS ---------- */
.web-form-container input[readonly],
.web-form-container textarea[readonly] {
    background: #f5f8fc !important;

    color: #475569 !important;

    border-color: #e2e8f0 !important;

    cursor: not-allowed !important;
}


/* ---------- FLIGHT FIELD ---------- */
.web-form-container input[data-fieldname="flight"] {
    font-weight: 600 !important;

    background: #f8fbff !important;

    border-color: #bfdbfe !important;
}


/* ---------- FLIGHT PRICE ---------- */
.web-form-container input[data-fieldname="flight_price"] {
    font-size: 18px !important;

    font-weight: 800 !important;

    color: #166534 !important;

    background: #f0fdf4 !important;

    border: 1px solid #86efac !important;

    box-shadow:
        0 3px 10px rgba(34, 197, 94, 0.08) !important;
}


/* ---------- AUTOMATICALLY FETCHED VALUES ---------- */
.web-form-container input[data-fieldname="source_airport_code"],
.web-form-container input[data-fieldname="destination_airport_code"],
.web-form-container input[data-fieldname="departure_date"],
.web-form-container input[data-fieldname="duration_of_flight"],
.web-form-container input[data-fieldname="departure_time"],
.web-form-container input[data-fieldname="gate_number"] {
    background: #f8fafc !important;

    color: #475569 !important;

    border-color: #e2e8f0 !important;
}


/* ---------- AIRPORT CODE LOOK ---------- */
.web-form-container
input[data-fieldname="source_airport_code"],
.web-form-container
input[data-fieldname="destination_airport_code"] {
    font-weight: 700 !important;

    letter-spacing: 1px !important;

    color: #1e40af !important;
}


/* ---------- FORM ROWS ---------- */
.web-form-container .row {
    margin-left: -8px !important;
    margin-right: -8px !important;
}


/* ---------- BOOKING BUTTON ---------- */
.web-form-container .btn-primary {
    width: 100% !important;

    min-height: 52px !important;

    border-radius: 12px !important;

    border: none !important;

    background:
        linear-gradient(
            135deg,
            #1d4ed8,
            #2563eb
        ) !important;

    color: #ffffff !important;

    font-size: 16px !important;

    font-weight: 800 !important;

    letter-spacing: 0.3px !important;

    margin-top: 18px !important;

    box-shadow:
        0 8px 18px rgba(37, 99, 235, 0.25) !important;

    transition:
        transform 0.2s ease,
        box-shadow 0.2s ease !important;
}


/* ---------- BUTTON HOVER ---------- */
.web-form-container .btn-primary:hover {
    background:
        linear-gradient(
            135deg,
            #1e40af,
            #1d4ed8
        ) !important;

    transform: translateY(-2px) !important;

    box-shadow:
        0 12px 25px rgba(37, 99, 235, 0.32) !important;
}


/* ---------- BUTTON CLICK ---------- */
.web-form-container .btn-primary:active {
    transform: translateY(0) !important;
}


/* ---------- DISCARD BUTTON ---------- */
.web-form-container .btn-secondary,
.web-form-container .btn-default {
    border-radius: 10px !important;

    min-height: 45px !important;

    font-weight: 600 !important;

    border: 1px solid #e2e8f0 !important;

    background: #f8fafc !important;

    color: #475569 !important;
}


/* ---------- STATUS BADGE ---------- */
.web-form-container .indicator {
    border-radius: 20px !important;

    padding: 4px 10px !important;

    font-weight: 600 !important;
}


/* ---------- SMALL AIRLINE DETAIL EFFECT ---------- */
.web-form-container .form-page .frappe-control {
    transition: transform 0.15s ease !important;
}


/* ---------- MOBILE ---------- */
@media (max-width: 768px) {

    .web-form-container {
        margin: 20px auto !important;
        padding: 10px !important;
    }

    .web-form-container .form-page {
        padding: 28px 22px !important;
        border-radius: 18px !important;
    }

    .web-form-container h1 {
        font-size: 25px !important;
    }

    .web-form-container .form-control {
        min-height: 44px !important;
    }

    .web-form-container .btn-primary {
        min-height: 50px !important;
    }
}
